    sources: ["https://targon.com", "https://docs.targon.com", "https://www.manifold.inc/releases", "https://github.com/manifold-inc/targon", "https://api.github.com/repos/manifold-inc/targon", "https://www.unsupervised.capital/writing/bittensors-ai-compute-subnets-collectively-reach-20m-arr", "https://ownyourmind.ai/tokenomics/targon-bittensor-confidential-compute/", "https://ownyourmind.ai/tokenomics/bittensor-subnets-where-the-revenue-is/", "https://oss.capital/oss-capital-leads-10-5m-series-a-in-manifold-labs-alongside-industry-legends/", "https://discord.gg/manifold"],
