    revenue_confidence: "confirmed_pre_revenue",
    revenue_evidence: "No product, no pricing page, no API, no customers. hone.training sells only the research narrative ('large language models trained by the many, owned by no one'). Their published roadmap defers any commercial API to Phase 3, 2027+ \u2014 see the Phase 3 description 'transitioning to API deployment for decentralized access' at https://subnetalpha.ai/subnet/hone/. Zero external revenue.",
    last_updated: "2026-08-12",
    sources: ["https://www.hone.training/", "https://www.hone.training/network", "https://github.com/manifold-inc/hone", "https://api.github.com/repos/manifold-inc/hone/commits?since=2026-02-01", "https://api.github.com/orgs/manifold-inc/repos", "https://subnetalpha.ai/subnet/hone/", "https://github.com/OpenKaito/openkaito", "https://api.taostats.io/api/subnet/identity/v1", "https://api.taostats.io/api/subnet/latest/v1?netuid=5", "https://api.taostats.io/api/metagraph/latest/v1?netuid=5"],
