    sources: ["https://taostats.io/subnets/35", "https://www.0xmarkets.io/", "https://github.com/General-Tao-Ventures/0xmarkets-docs", "https://github.com/General-Tao-Ventures/0xmarkets-docs/blob/main/reference/fee-schedule.md", "https://github.com/General-Tao-Ventures/0xmarkets-docs/blob/main/security/audits.md", "https://github.com/General-Tao-Ventures/0xmarkets-docs/blob/main/changelog.md", "https://github.com/General-Tao-Ventures/0xmarkets-docs/blob/main/litepaper.md", "https://hashlock.com/audits/cartha", "https://hackenproof.com/companies/0xmarkets", "https://api.llama.fi/protocols", "https://github.com/General-Tao-Ventures", "https://0xmarkets.io/discord"],
