    sources: ["https://github.com/TensorLink-AI/cascade", "https://api.taostats.io/api/subnet/identity/v1", "https://testnet.cascadesub.net/", "https://taostats.io/subnets/91", "https://x.com/CryptoZPunisher/status/2071720725950439889", "https://backprop.finance/dtao/subnets/91-bitstarter-1/liquidityProviders", "https://ownyourmind.ai/tokenomics/bittensor-subnets-where-the-revenue-is/", "https://cascadesub.net (currently redirects to https://testnet.cascadesub.net/)"],
