    sources: ["https://verathos.ai/skill.txt", "https://api.verathos.ai/v1/network/stats", "https://api.verathos.ai/v1/models", "https://github.com/verathos-ai/verathos", "https://api.github.com/repos/verathos-ai/verathos", "https://api.github.com/repos/verathos-ai/verathos/contributors", "https://api.github.com/repos/verathos-ai/verathos/git/trees/main?recursive=1", "https://verathos.ai/", "https://verathos.ai/about", "https://taostats.io/subnets/96", "https://verathos.ai", "https://discord.com/channels/799672011265015819/1480627157406584945"],
