    sources: ["https://taostats.io/subnets/118", "https://heyditto.ai/", "https://heyditto.ai/pricing/", "https://www.tao.media/ditto-sn118-the-open-source-agentic-operating-system/", "https://taoprotocol.org/ditto-sn118-miners-are-beating-the-team-that-built-it-on-its-own-benchmark/", "https://github.com/ditto-assistant", "https://github.com/ditto-assistant/dittobench-api", "https://raw.githubusercontent.com/ditto-assistant/ditto-subnet/main/README.md", "https://api.github.com/orgs/ditto-assistant/repos", "https://ownyourmind.ai/tokenomics/bittensor-subnets-where-the-revenue-is/"],
